def _proba(evenement, univers):
    """Probabilité exacte d'un événement sur un univers fini équiprobable."""
    univers = list(univers)
    return F(sum(1 for w in univers if evenement(w)), len(univers))


def _dot(u, v):
    return sum(i * j for i, j in zip(u, v))


def _vec(A, B):
    return tuple(j - i for i, j in zip(A, B))


def _d2(A, B):
    return sum((j - i) ** 2 for i, j in zip(A, B))


def _suite_inv(count):
    """u_0 = 1, u_{n+1} = u_n + 1/u_n (valeurs exactes)."""
    u = [F(1)]
    while len(u) < count:
        u.append(u[-1] + 1 / u[-1])
    return u


def _arrangements(lettres):
    """Ordres de tirage équiprobables (sans remise) de boules discernables, en chaînes."""
    return ["".join(o) for o in permutations(lettres)]


def _ens_trig(expr_ok, debut, fin, pas):
    """Réels kπ/pas de [debut ; fin[ (en multiples de π) vérifiant expr_ok."""
    return [F(i, pas) for i in range(int(debut * pas), int(fin * pas)) if expr_ok(F(i, pas) * PI)]


